      {loading ? <DataState icon={LoaderCircle} text="Đang tải dữ liệu từ hệ thống..." spinning /> : error ? <DataState icon={AlertCircle} text={error.message || 'Không thể tải dữ liệu.'} action={reload} /> : content.length === 0 ? <DataState icon={Inbox} text={keyword ? `Không tìm thấy kết quả cho “${keyword}”.` : emptyMessage} /> : <><div className="table-scroll"><table><thead><tr>{columns.map((column) => <th key={column.key}>{column.label}</th>)}{(crud?.detail || crud?.previewField || crud?.previewEndpoint || crud?.addStudent || crud?.quickStatus || canEdit || canDelete || crud?.resetPassword) && <th />}</tr></thead><tbody>{content.map((row, index) => <tr key={getRowKey(row, index)}>{columns.map((column) => <td key={column.key} data-label={column.label}>{renderCell(row, column)}</td>)}{(crud?.detail || crud?.previewField || crud?.previewEndpoint || crud?.addStudent || crud?.quickStatus || canEdit || canDelete || crud?.resetPassword) && <td className="table-actions" data-label="Thao tác"><div className="inline-actions">{crud?.quickStatus && quickStatusOptions(crud.quickStatus, row).length > 0 && <select className="quick-status-select" value="" disabled={saving} aria-label={`Đổi trạng thái ${getDisplayName(row)}`} onChange={(event) => { const nextStatus = event.target.value; if (nextStatus && nextStatus !== row[crud.quickStatus.field]) { setStatusReason(''); setConfirm({ type: 'status', row, nextStatus }); } }}><option value="">Đổi trạng thái</option>{quickStatusOptions(crud.quickStatus, row).map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}</select>}{crud?.addStudent && <button className="add-member" disabled={saving} onClick={() => openAddStudent(row)} title="Thêm sinh viên vào nhóm" aria-label={`Thêm sinh viên vào ${getDisplayName(row)}`}><UserPlus size={15} /></button>}{(crud?.previewEndpoint ? (!crud.previewField || valueAt(row, crud.previewField)) : (crud?.previewField && valueAt(row, crud.previewField))) && <button className="preview" onClick={() => openPreview(row)} title="Xem trước tệp" aria-label={`Xem trước ${getDisplayName(row)}`}><Eye size={15} /></button>}{crud?.detail && <button className="view" onClick={() => openDetail(row)} title="Xem chi tiết" aria-label={`Xem chi tiết ${getDisplayName(row)}`}><Eye size={15} /></button>}{crud?.resetPassword && <button className="reset" onClick={() => setConfirm({ type: 'reset', row })} title="Đặt lại mật khẩu"><KeyRound size={15} /></button>}{canEdit && <button onClick={() => setConfirm({ type: 'edit', row })} title="Chỉnh sửa"><Edit3 size={15} /></button>}{canDelete && <button className="danger" onClick={() => requestRemove(row)} title="Xóa"><Trash2 size={15} /></button>}</div></td>}</tr>)}</tbody></table></div><div className="table-footer"><span>Hiển thị {content.length} trong tổng số {totalElements} kết quả</span><div><button disabled={first} onClick={() => setPage(Math.max(0, page - 1))}>Trước</button><button className="active">{page + 1}</button><button disabled={last} onClick={() => setPage(Math.min(totalPages - 1, page + 1))}>Sau</button></div></div></>}
